"use strict";(globalThis.webpackChunklinux_cleanup_docs||=[]).push([[1278],{42562(e){e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"desktop-1.0.2","metadata":{"permalink":"/feed/desktop-1.0.2","source":"@site/blog/2026-11-22-desktop-1-0-2.md","title":"Desktop 1.0.2","description":"Clearer wording on the Updates screen and a working check command on the errors screen.","date":"2026-11-22T09:40:00.000Z","tags":[{"inline":true,"label":"desktop","permalink":"/feed/tags/desktop"},{"inline":true,"label":"release","permalink":"/feed/tags/release"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"desktop-1.0.2","title":"Desktop 1.0.2","description":"Clearer wording on the Updates screen and a working check command on the errors screen.","date":"2026-11-22T09:40","tags":["desktop","release"]},"unlisted":false,"nextItem":{"title":"Desktop 1.0.1","permalink":"/feed/desktop-1.0.1"}},"content":"Clearer wording on the Updates screen, and the errors screen now copies a command that works:\\n`npx -y linux-cleanup --self-test`. The app updates itself."},{"id":"desktop-1.0.1","metadata":{"permalink":"/feed/desktop-1.0.1","source":"@site/blog/2026-11-22-desktop-1-0-1.md","title":"Desktop 1.0.1","description":"Error reports with no paths or file names, a walkthrough with real screens, a Get linux-cleanup page and steadier page tours.","date":"2026-11-22T07:40:00.000Z","tags":[{"inline":true,"label":"desktop","permalink":"/feed/tags/desktop"},{"inline":true,"label":"release","permalink":"/feed/tags/release"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"desktop-1.0.1","title":"Desktop 1.0.1","description":"Error reports with no paths or file names, a walkthrough with real screens, a Get linux-cleanup page and steadier page tours.","date":"2026-11-22T07:40","tags":["desktop","release"]},"unlisted":false,"prevItem":{"title":"Desktop 1.0.2","permalink":"/feed/desktop-1.0.2"},"nextItem":{"title":"Desktop 1.0.0","permalink":"/feed/desktop-1.0.0"}},"content":"Error reports reach us without paths or file names, the walkthrough shows real screens, and Help has a Get\\nlinux-cleanup page listing every place it runs.\\n\\n\x3c!-- truncate --\x3e\\n\\nPage tours keep each step in view as you move through them. The app updated itself from 1.0.0. See\\n[installing the desktop app](/desktop/install)."},{"id":"desktop-1.0.0","metadata":{"permalink":"/feed/desktop-1.0.0","source":"@site/blog/2026-11-21-desktop-1-0-0.md","title":"Desktop 1.0.0","description":"The first desktop release, an AppImage and .deb for x86_64 Linux bundling CLI 2.1.0.","date":"2026-11-21T14:00:00.000Z","tags":[{"inline":true,"label":"desktop","permalink":"/feed/tags/desktop"},{"inline":true,"label":"release","permalink":"/feed/tags/release"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"desktop-1.0.0","title":"Desktop 1.0.0","description":"The first desktop release, an AppImage and .deb for x86_64 Linux bundling CLI 2.1.0.","date":"2026-11-21T14:00","tags":["desktop","release"]},"unlisted":false,"prevItem":{"title":"Desktop 1.0.1","permalink":"/feed/desktop-1.0.1"},"nextItem":{"title":"CLI 2.1.0","permalink":"/feed/cli-2.1.0"}},"content":"The first desktop release: the all-safe cleanup in a window, with a dry run before every real run and a receipt\\nafter it.\\n\\n\x3c!-- truncate --\x3e\\n\\nAppImage and .deb for x86_64 Linux, bundling CLI 2.1.0. It updates itself from signed releases. Start with\\n[installing the desktop app](/desktop/install)."},{"id":"cli-2.1.0","metadata":{"permalink":"/feed/cli-2.1.0","source":"@site/blog/2026-11-21-cli-2-1-0.md","title":"CLI 2.1.0","description":"--json-events streams local, versioned JSON events for --scan and non-interactive all-safe runs, dry runs included.","date":"2026-11-21T12:00:00.000Z","tags":[{"inline":true,"label":"cli","permalink":"/feed/tags/cli"},{"inline":true,"label":"release","permalink":"/feed/tags/release"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"cli-2.1.0","title":"CLI 2.1.0","description":"--json-events streams local, versioned JSON events for --scan and non-interactive all-safe runs, dry runs included.","date":"2026-11-21T12:00","tags":["cli","release"]},"unlisted":false,"prevItem":{"title":"Desktop 1.0.0","permalink":"/feed/desktop-1.0.0"},"nextItem":{"title":"CLI 2.0.1","permalink":"/feed/cli-2.0.1"}},"content":"`--json-events` streams local, versioned JSON events for `--scan` and non-interactive `--all-safe --yes`.\\n\\n\x3c!-- truncate --\x3e\\n\\nAdding `--dry-run` to all-safe reports proposed paths without deleting them. The stream can contain full local\\npaths, so keep it on the machine. The [JSON events reference](/reference/json-events) and the [changelog](/changelog)\\nhave the details."},{"id":"cli-2.0.1","metadata":{"permalink":"/feed/cli-2.0.1","source":"@site/blog/2026-11-21-cli-2-0-1.md","title":"CLI 2.0.1","description":"The README lists every place linux-cleanup is released. No change to what the script does.","date":"2026-11-21T10:00:00.000Z","tags":[{"inline":true,"label":"cli","permalink":"/feed/tags/cli"},{"inline":true,"label":"release","permalink":"/feed/tags/release"}],"hasTruncateMarker":false,"authors":[],"frontMatter":{"slug":"cli-2.0.1","title":"CLI 2.0.1","description":"The README lists every place linux-cleanup is released. No change to what the script does.","date":"2026-11-21T10:00","tags":["cli","release"]},"unlisted":false,"prevItem":{"title":"CLI 2.1.0","permalink":"/feed/cli-2.1.0"},"nextItem":{"title":"CLI 2.0.0","permalink":"/feed/cli-2.0.0"}},"content":"The README lists every place linux-cleanup is released. No change to what the script does."},{"id":"cli-2.0.0","metadata":{"permalink":"/feed/cli-2.0.0","source":"@site/blog/2026-11-10-cli-2-0-0.md","title":"CLI 2.0.0","description":"linux-cleanup 2.0.0 adds --dry-run, a release-record check on start and --refresh-app.","date":"2026-11-10T12:00:00.000Z","tags":[{"inline":true,"label":"cli","permalink":"/feed/tags/cli"},{"inline":true,"label":"release","permalink":"/feed/tags/release"}],"hasTruncateMarker":true,"authors":[],"frontMatter":{"slug":"cli-2.0.0","title":"CLI 2.0.0","description":"linux-cleanup 2.0.0 adds --dry-run, a release-record check on start and --refresh-app.","date":"2026-11-10T12:00","tags":["cli","release"]},"unlisted":false,"prevItem":{"title":"CLI 2.0.1","permalink":"/feed/cli-2.0.1"}},"content":"Added `--dry-run`, a public release-record check on start, and `--refresh-app` for the persistent CLI copy.\\n\\n\x3c!-- truncate --\x3e\\n\\nNormal release notices allow the first run and block from the next start; urgent notices block an older copy at\\nonce. Offline runs continue. A dry run does not remove cleanup targets or change settings, though it may write a\\nlocal log and update-check state. Read the [changelog](/changelog) for the full entry."}]}}')}}]);